-- Each S3 object contains one JSON array generated by the weather Lambda.
-- Ion SerDe does not support DOUBLE, so numeric fields use DECIMAL.
-- If the weather table already exists with DOUBLE fields, run:
-- DROP TABLE weather;
-- before running this statement.
CREATE EXTERNAL TABLE IF NOT EXISTS weather (
  records array<struct<
    timestamp:string,
    latitude:decimal(12,6),
    longitude:decimal(12,6),
    wind_speed:decimal(12,6),
    wind_direction:decimal(12,6),
    wave_height:decimal(12,6),
    water_temperature:decimal(12,6),
    air_temperature:decimal(12,6),
    cloud_cover:decimal(12,6)
  >>
)
ROW FORMAT SERDE 'com.amazon.ionhiveserde.IonHiveSerDe'
WITH SERDEPROPERTIES ('ion.records.path_extractor' = '()')
STORED AS ION
LOCATION 's3://sea-routes-back/weather/';
